#!/bin/bash
S=$(cd "$(dirname "$0")" && pwd); B=${SPECSHIP_BIN:-specship}; cd $S
mkdir -p old; mv runs old/runs-$(date +%s) 2>/dev/null
for n in sidebar header login; do mkdir -p author-$n/skill/references; cp ${SPECSHIP_REPO:?set SPECSHIP_REPO to the specship checkout}/skills/design-md/SKILL.md author-$n/skill/; cp ${SPECSHIP_REPO:?set SPECSHIP_REPO to the specship checkout}/skills/design-md/references/authored-sections.md author-$n/skill/references/; rm -f author-$n/design.md author-$n/author-out.json; $B design extract design-$n/snapshot.html --out author-$n/design.md --title "$n" -p $S >/dev/null; done
for n in sidebar header login; do (cd $S/author-$n && claude -p "You are running step 3 of the design-md skill. Read ./skill/SKILL.md and ./skill/references/authored-sections.md, then read ./design.md. Fill in design.md's authored sections (Screens & layout, Components & states, Interactions & motion, Responsive behaviour, Assets) following those instructions exactly: every value copied from the Generated reference with its selector, every styled state listed (hover, focus, disabled), no approximate wording, and delete each <!-- design-md: ... --> hint you replace. Do not touch the generated block or any other section. Edit design.md in place." --model haiku --strict-mcp-config --mcp-config $S/empty-mcp.json --allowedTools "Read,Write,Edit" --disallowedTools "Bash,Glob,Grep,WebFetch,WebSearch,Task,Agent" --setting-sources "" --output-format json < /dev/null > author-out.json 2>/dev/null) & done; wait
for n in sidebar header login; do echo "author $n: $(node -e "const o=JSON.parse(require('fs').readFileSync('$S/author-$n/author-out.json','utf8'));process.stdout.write(Object.keys(o.modelUsage).join(',')+' \$'+o.total_cost_usd.toFixed(3))") $($B design check author-$n/design.md -p $S | tail -1)"; done
dims() { case $1 in sidebar) echo "232 900";; header) echo "1208 261";; login) echo "1280 800";; esac; }
(for n in sidebar header login; do read w h <<< "$(dims $n)"; for r in 1 2 3; do DESIGN_MD=$S/author-$n/design.md ./run-arm.sh $n designmd $r $w $h haiku & DESIGN_MD=$S/author-$n/design.md ./run-arm.sh $n designmd $r $w $h flash & done; done; wait) >/dev/null 2>&1
(for n in sidebar header login; do read w h <<< "$(dims $n)"; ./run-arm.sh $n screenshot 1 $w $h haiku & ./run-arm.sh $n screenshot 1 $w $h flash & done; wait) >/dev/null 2>&1
./score-all.sh
